CREATE TABLE IF NOT EXISTS steamfake_jogos (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome VARCHAR(150) NOT NULL,
  slug VARCHAR(160) NOT NULL,
  descricao TEXT NOT NULL,
  imagem VARCHAR(255) NOT NULL,
  plataforma VARCHAR(60) NOT NULL DEFAULT 'PC',
  genero VARCHAR(100) NOT NULL,
  avaliacao DECIMAL(2,1) NOT NULL DEFAULT 0.0,
  preco_original DECIMAL(10,2) NOT NULL,
  preco_atual DECIMAL(10,2) NOT NULL,
  desconto DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  promocao_status VARCHAR(80) NOT NULL DEFAULT 'Preço regular',
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  atualizado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_steamfake_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE nome=VALUES(nome), preco_original=VALUES(preco_original), preco_atual=VALUES(preco_atual), desconto=VALUES(desconto), atualizado_em=CURRENT_TIMESTAMP;
